<?php
namespace App\Http\Controllers\Procurement;use App\Http\Controllers\Controller;use App\Models\{InventoryItem,InventoryStock,Store};use Illuminate\Http\Request;
class StoreController extends Controller{public function index(Request $r){$p=auth()->user()->property_id;$stores=Store::where('property_id',$p)->withCount('stocks')->get();$selected=$r->integer('store_id')?Store::where('property_id',$p)->find($r->integer('store_id')):$stores->first();$stocks=$selected?InventoryStock::with('item')->where('store_id',$selected->id)->orderByDesc('quantity')->paginate(50):collect();return view('procurement.stores.index',compact('stores','selected','stocks'));}public function store(Request $r){$d=$r->validate(['name'=>'required|max:255','code'=>'required|max:30','type'=>'required|in:main,kitchen,bar,housekeeping,maintenance,other','location'=>'nullable|max:255']);$d['property_id']=auth()->user()->property_id;Store::create($d);return back()->with('success','Store created.');}}